// binding.go
package streaming
// #include "streaming.h"
import "C"
import (
    "runtime"
    "sync"
    "unsafe"
)

type EventCallback func(string) error

var (
    callbacks   = make(map[uintptr]EventCallback)
    cbMu        sync.Mutex
)

//export goEventCallback
func goEventCallback(cBatch *C.char, ctx unsafe.Pointer) {
    id := uintptr(ctx)
    cbMu.Lock()
    cb := callbacks[id]
    cbMu.Unlock()
    if cb == nil {
        return
    }
    batch := C.GoString(cBatch)
    _ = cb(batch)
}

func StartStream(batchSize int, onEvent EventCallback) error {
    // store callback and start streaming
    id := uintptr(unsafe.Pointer(&onEvent))
    cbMu.Lock()
    callbacks[id] = onEvent
    cbMu.Unlock()
    C.register_event_source(C.event_cb(C.goEventCallback), unsafe.Pointer(id))
    C.start_streaming(C.size_t(batchSize), C.size_t(batchSize))
    runtime.KeepAlive(onEvent)
    return nil
}
